package com.rohit.inventory.security;
import com.fasterxml.jackson.databind.ObjectMapper; import com.rohit.inventory.dto.response.ErrorResponse; import jakarta.servlet.http.*; import java.io.IOException; import java.time.Instant; import java.util.Map; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component;
@Component public class RestAccessDeniedHandler implements AccessDeniedHandler { private final ObjectMapper objectMapper; public RestAccessDeniedHandler(ObjectMapper objectMapper) { this.objectMapper=objectMapper; } public void handle(HttpServletRequest req,HttpServletResponse res,AccessDeniedException ex) throws IOException { res.setStatus(403); res.setContentType(MediaType.APPLICATION_JSON_VALUE); objectMapper.writeValue(res.getOutputStream(),new ErrorResponse(false,"You do not have permission to perform this action","ACCESS_DENIED",req.getRequestURI(),Map.of(),Instant.now())); } }
